// Normalize the POD form submission and read the uploaded photo into base64.
const item = $input.first();
const j = item.json || {};
const bin = item.binary || {};
const prop = bin.photo ? 'photo' : (Object.keys(bin).length ? Object.keys(bin)[0] : null);
let imgB64 = '';
let imgMime = 'image/jpeg';
if (prop) {
  imgMime = bin[prop].mimeType || bin[prop].mime || 'image/jpeg';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, prop);
    if (buf && buf.length > 100) imgB64 = buf.toString('base64');
  } catch (e) {
    imgB64 = '';
  }
}
const waybill = String(j.waybill || '').trim();
const recipient = String(j.recipient_name || '').trim();
const notes = String(j.notes || '').trim();
return [{
  json: {
    pod_id: 'POD-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase(),
    waybill: waybill,
    recipient_name: recipient,
    notes: notes,
    submitted_at: $now.toISO(),
    has_photo: imgB64.length > 100,
    img_b64: imgB64,
    img_mime: imgMime
  }
}];

// Find the delivery row that matches the submitted waybill.
const norm = $('Normalize submission and check photo').first().json;
const key = String(norm.waybill || '').trim().toUpperCase();
const rows = $input.all().map(i => i.json);
const hit = rows.find(r => String(r.waybill || '').trim().toUpperCase() === key);
if (hit) {
  return [{
    json: {
      found: true,
      delivery: hit,
      waybill: key,
      pod_id: norm.pod_id,
      recipient_name: norm.recipient_name,
      notes: norm.notes,
      submitted_at: norm.submitted_at,
      has_photo: norm.has_photo,
      img_b64: norm.img_b64,
      img_mime: norm.img_mime
    }
  }];
}
return [{
  json: {
    found: false,
    waybill: key,
    pod_id: norm.pod_id,
    recipient_name: norm.recipient_name,
    notes: norm.notes,
    submitted_at: norm.submitted_at,
    has_photo: norm.has_photo,
    img_b64: norm.img_b64,
    img_mime: norm.img_mime
  }
}];

// Build the OpenAI vision request. Only runs when a photo exists.
const ctx = $input.first().json;
const img = 'data:' + (ctx.img_mime || 'image/jpeg') + ';base64,' + ctx.img_b64;
const system = 'You verify delivery proof photos for a courier company. A driver submits a photo at the customer doorstep as proof of delivery. Accept as ok any photo that plausibly shows a delivery scene: a parcel, a box, a package, an entrance, a doorstep, or a person receiving goods. Reply mismatch only when the photo is clearly unusable as proof: completely black, extremely blurry, missing, or showing unrelated content such as a selfie, a receipt, a screenshot, or text-only graphics. Reply with ONLY valid JSON: {"signal": "ok" or "mismatch", "summary": string}. Keep summary to one short sentence.';
const userText = 'Waybill ' + ctx.waybill + '. Stated recipient: ' + ctx.recipient_name + '. Driver note: ' + ctx.notes;
return [{
  json: {
    reqObj: {
      model: 'gpt-4o-mini',
      temperature: 0.1,
      max_tokens: 400,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: [{ type: 'text', text: userText }, { type: 'image_url', image_url: { url: img } }] }
      ]
    }
  }
}];

// Parse the vision JSON and reattach the delivery context.
const ctx = $('Match delivery row').first().json;
let raw = '';
try {
  raw = $json.choices[0].message.content || '';
} catch (e) {
  raw = '';
}
raw = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let signal = 'mismatch';
let summary = 'Could not read the vision model output.';
try {
  const p = JSON.parse(raw);
  if (p.signal === 'ok' || p.signal === 'mismatch') signal = p.signal;
  if (p.summary) summary = String(p.summary);
} catch (e) {}
return [{
  json: Object.assign({}, ctx, { signal: signal, ai_summary: summary })
}];

// Collect deliveries still in transit that are older than 2 days.
const rows = $input.all().map(i => i.json);
const now = new Date();
function daysOld(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || '').trim());
  if (!m) return 9999;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return Math.floor((now - d) / 86400000);
}
const pending = rows.filter(r => {
  const st = String(r.status || '').trim();
  return (st === '' || st === 'In Transit' || st === 'Pending') && daysOld(r.assigned_date) > 2;
});
if (!pending.length) return [];
const lines = pending.map(r => '- ' + (r.waybill || '?') + ' to ' + (r.customer_name || '?') + ' (' + (r.driver || r.driver_email || 'no driver') + '), assigned ' + (r.assigned_date || '?')).join('\n');
return [{
  json: {
    pending_count: pending.length,
    waybill_list: lines
  }
}];

// Parse the nudge agent output.
const rawItem = $input.first();
const raw = rawItem.json.output !== undefined ? rawItem.json.output : (rawItem.json.message ? rawItem.json.message.content : '');
let text = String(raw == null ? '' : raw).trim();
text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let nudge = '';
try {
  const p = JSON.parse(text);
  nudge = String(p.nudge_text || '').trim();
} catch (e) {}
if (!nudge) nudge = text;
return [{ json: { nudge_text: nudge } }];

// Summarize the last 7 days of proof log entries.
const rows = $input.all().map(i => i.json);
const now = new Date();
const cut = new Date(now.getTime() - 7 * 86400000);
function ts(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})T?/.exec(String(s || '').trim());
  return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null;
}
const week = rows.filter(r => {
  const d = ts(r.created_at);
  return d && d >= cut && d <= now;
});
const byStatus = {};
week.forEach(r => {
  const st = String(r.status || 'Unknown').trim();
  byStatus[st] = (byStatus[st] || 0) + 1;
});
const breakdown = Object.keys(byStatus).length
  ? Object.entries(byStatus).map(([k, v]) => '- ' + k + ': ' + v).join('\n')
  : 'No entries';
return [{
  json: {
    week_total: week.length,
    breakdown: breakdown
  }
}];

// Parse the summary agent output.
const rawItem = $input.first();
const raw = rawItem.json.output !== undefined ? rawItem.json.output : (rawItem.json.message ? rawItem.json.message.content : '');
let text = String(raw == null ? '' : raw).trim();
text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let summary = '';
try {
  const p = JSON.parse(text);
  summary = String(p.summary_text || '').trim();
} catch (e) {}
if (!summary) summary = text;
return [{ json: { summary_text: summary } }];
